python3 << 'EOF'
import re

# Parse the input sequences
with open('/app/sequences.fasta', 'r') as f:
    content = f.read()

sequences = {}
current_header = None
current_seq = []

for line in content.strip().split('\n'):
    if line.startswith('>'):
        if current_header:
            sequences[current_header] = ''.join(current_seq)
        current_header = line[1:]
        current_seq = []
    else:
        current_seq.append(line)

if current_header:
    sequences[current_header] = ''.join(current_seq)

for name, seq in sequences.items():
    print(f"{name}: {len(seq)} bp")
    if len(seq) <= 300:
        print(f"Sequence: {seq}")
    else:
        print(f"First 100: {seq[:100]}")
        print(f"Last 100: {seq[-100:]}")
    print()
EOF
